"""Regenerate the static pages after editing data/site.json. Python standard library only."""
raise SystemExit('This project now uses React. Run npm run build instead. The legacy HTML snapshot is in legacy-html/.')
import json
from pathlib import Path
from html import escape as esc

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / 'data/site.json').read_text(encoding='utf-8'))

def image(item, size=1200, hero=False):
    stem = Path(item['file']).stem
    return f'<img src="images/web/{stem}-{size}.jpg" srcset="images/web/{stem}-600.jpg 600w, images/web/{stem}-1200.jpg 1200w, images/web/{stem}-1920.jpg 1920w" sizes="{("100vw" if hero else "(max-width: 700px) 100vw, 50vw")}" width="{item["width"]}" height="{item["height"]}" alt="{esc(item["alt"])}" {("fetchpriority=\"high\"" if hero else "loading=\"lazy\"")} decoding="async">'

photos = data['photos']
cars = [p for p in photos if p['category'] == 'automotive']
portraits = [p for p in photos if p['category'] == 'portrait']

def photo(item, number):
    return f'<button class="gallery-item" type="button" data-photo="images/web/{Path(item["file"]).stem}-1920.jpg" data-caption="{esc(item["alt"])}" aria-label="Enlarge: {esc(item["alt"])}">{image(item)}<span class="photo-caption"><span>{esc(item["title"])}</span><span>{number:02d} ↗</span></span></button>'

def cta(title="Let's Create Something Extraordinary.", label='Start a conversation', href='booking.html#inquiry'):
    return f'<section class="cta section"><span class="eyebrow">YOUR NEXT FRAME</span><h2>{title}</h2><a class="button" href="{href}">{label} <span>↗</span></a></section>'

def hero(item, eyebrow, heading, text='', home=False):
    return f'<section class="hero {"home-hero" if home else "portfolio-hero"}">{image(item,1920,True)}<div class="hero-shade"></div><div class="hero-content"><p class="eyebrow">{eyebrow}</p><h1>{heading}</h1><p class="hero-subtitle">{text}</p>{("<div class=\"hero-actions\"><a class=\"button\" href=\"#portfolio\">Explore Portfolio <span>↗</span></a><a class=\"text-link\" href=\"booking.html#inquiry\">Book a Session <span>↗</span></a></div>" if home else "")}</div><div class="hero-bottom"><span>{"AUTOMOTIVE & PORTRAIT" if home else "A STUDY IN LIGHT & CHARACTER"}</span><a href="#portfolio">SCROLL TO EXPLORE ↓</a><span>PORTFOLIO / {"01" if home else "02" if item in cars else "03"}</span></div></section>'

def shell(filename, title, description, content):
    nav = ''.join(f'<a href="{url}" {("aria-current=\"page\"" if filename == url else "")}>{label}</a>' for url,label in [('index.html','Home'),('cars.html','Cars'),('portraits.html','Portraits'),('booking.html','Booking & Pricing')])
    page = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#101010"><title>{title} | Your Name Photography</title><meta name="description" content="{esc(description)}"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/config.js" defer></script><script src="assets/main.js" defer></script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="index.html" aria-label="Nino Ponchev Photography home"><span class="brand-mark">NP</span><span class="brand-name">NINO PONCHEV<span>PHOTOGRAPHY</span></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{nav}<a class="nav-cta" href="booking.html#inquiry">Let's talk <span>↗</span></a></nav></header>
<main id="main">{content}</main><footer><div class="footer-top"><a class="brand footer-brand" href="index.html">YOUR NAME<span>PHOTOGRAPHY</span></a><p>Motion. Emotion. A different perspective.</p><div class="footer-contact"><a href="https://www.instagram.com/your_username/" rel="noopener noreferrer">Instagram ↗ (placeholder)</a><a href="mailto:hello@example.com">hello@example.com (placeholder)</a></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> Your Name Photography</span><div><a href="impressum.html">Impressum</a><a href="privacy.html">Privacy Policy</a><a href="#main">Back to top ↑</a></div></div></footer>
<dialog class="lightbox" aria-label="Photo viewer"><div class="lightbox-toolbar"><span class="lightbox-count"></span><button type="button" data-close aria-label="Close photo viewer">Close ×</button></div><button class="lightbox-prev" type="button" aria-label="Previous photograph">←</button><figure><img alt=""><figcaption></figcaption></figure><button class="lightbox-next" type="button" aria-label="Next photograph">→</button></dialog></body></html>'''
    (ROOT / filename).write_text(page, encoding='utf-8')

home = hero(cars[2], 'INDEPENDENT PHOTOGRAPHY / AUTOMOTIVE & PORTRAIT', 'Capturing Motion.<br><em>Creating Emotion.</em>', 'Automotive & Portrait Photography', True)
home += '<section class="section" id="portfolio"><div class="section-heading"><div><p class="eyebrow">01 / TWO WORLDS. ONE PERSPECTIVE.</p><h2>Driven by detail.<br><em>Defined by feeling.</em></h2></div><p>From sculpted metal to unguarded moments.<br>Explore the stories on either side of the lens.</p></div><div class="categories">'
for p, name, href, sub in [(cars[0],'Automotive Photography','cars.html','Design. Detail. Presence.'),(portraits[2],'Portrait Photography','portraits.html','Personality. Light. Connection.')]:
    home += f'<a class="category" href="{href}">{image(p)}<div><span class="eyebrow">{sub}</span><h3>{name} <span>↗</span></h3></div></a>'
home += '</div></section><section class="section featured"><div class="section-heading"><div><p class="eyebrow">02 / SELECTED WORK</p><h2>A closer <em>look.</em></h2></div><p>A selection of automotive and portrait work.<br>Click a photograph to see the whole picture.</p></div><div class="gallery editorial">'
home += ''.join(photo(p,i+1) for i,p in enumerate([cars[1],portraits[0],portraits[3],cars[3],portraits[1],cars[2]]))
home += '</div></section><section class="section about"><div><p class="eyebrow">03 / BEHIND THE LENS</p><h2>Every frame<br>starts with<br><em>a connection.</em></h2></div><div><span class="small-label">YOUR NAME / PHOTOGRAPHER</span><p class="large-copy">I’m [Your Name], a photographer drawn to character — in the lines of a vehicle and in the people in front of my lens.</p><p>[Add your background, location, and approach here.] My work brings together thoughtful composition, expressive light, and attention to the details that make a photograph feel personal.</p><a class="text-link" href="booking.html#inquiry">Let’s make your vision tangible <span>↗</span></a></div></section>' + cta()
shell('index.html','Automotive & Portrait Photography','Cinematic automotive photography and expressive portraits. Explore selected work and plan your next photography session.',home)

for filename, items, category, intro, services in [('cars.html',cars,'Automotive','The lines. The light. The feeling. Thoughtful automotive imagery that brings the design, details, and character of your vehicle into focus.',['Automotive portraits','Detail photography','Automotive lifestyle photography']),('portraits.html',portraits,'Portrait','Authentic personality, expressive light, and space to be yourself. Portraits that capture a feeling as much as a face.',['Individual portraits','Lifestyle portraits','Outdoor photography','Professional headshots'])]:
    body = hero(items[2],f'{"01" if category == "Automotive" else "02"} / THE PORTFOLIO',f'{category}<br><em>Photography.</em>',intro)
    body += '<section class="section" id="portfolio"><div class="section-heading"><div><p class="eyebrow">THE COLLECTION</p><h2>Character in <em>focus.</em></h2></div><p>Explore the full frame.<br>Select any photograph to enlarge.</p></div><div class="gallery">' + ''.join(photo(p,i+1) for i,p in enumerate(items)) + '</div></section>'
    body += '<section class="section services"><div><p class="eyebrow">MADE AROUND YOU</p><h2>Your story.<br><em>Your session.</em></h2></div><div>' + ''.join(f'<div class="service-row"><span>0{i+1}</span><h3>{s}</h3><span>↗</span></div>' for i,s in enumerate(services)) + '</div></section>'
    body += cta(label='Book an Automotive Shoot' if category=='Automotive' else 'Book a Portrait Session',href=f'booking.html?type={category.lower()}#inquiry')
    shell(filename,f'{category} Photography',intro,body)

booking = '<section class="section page-intro"><p class="eyebrow">LET’S MAKE SOMETHING MEANINGFUL</p><h1>A vision.<br><em>A session. A story.</em></h1><p>Choose a starting point. Tell me what you have in mind.<br>We’ll shape the details together.</p></section><section class="section pricing" id="pricing"><div class="section-heading"><div><p class="eyebrow">01 / BOOKING & PRICING</p><h2>Space for <em>your vision.</em></h2></div><p class="placeholder-note">Example packages · editable placeholder prices.<br>Final prices and package details are subject to confirmation.</p></div><div class="price-grid">'
for package in data['packages']:
    premium = package['level'] == 'Premium'
    booking += f'<article class="price-card {"premium" if premium else ""}"><div class="price-category">{package["type"].upper()}<span>{"MORE TIME, MORE POSSIBILITIES" if premium else "THE STARTING POINT"}</span></div><h3>{package["level"]}</h3><p class="price">€{package["price"]}<span> / session</span></p><ul>' + ''.join(f'<li>{esc(detail)}</li>' for detail in package['details']) + f'</ul><a class="button {"" if premium else "outline"}" href="#inquiry" data-package="{package["id"]}">Choose {package["level"]} <span>↗</span></a></article>'
booking += '</div></section><section class="section inquiry" id="inquiry"><div><p class="eyebrow">02 / START A CONVERSATION</p><h2>Tell me<br><em>your idea.</em></h2><p>A place, a person, a car, a feeling.<br>It all starts with a conversation.</p><p class="form-notice" id="integration-notice">Preview form: online inquiries are not connected yet. This form cannot send a message until a submission service is configured.</p></div><form id="booking-form"><div class="form-grid"><label>Full name <span>*</span><input name="name" autocomplete="name" required maxlength="120" placeholder="Your full name"></label><label>Email address <span>*</span><input type="email" name="email" autocomplete="email" required maxlength="200" placeholder="you@example.com"></label><label>Photography type <span>*</span><select name="type" required><option value="">Select photography type</option><option value="automotive">Automotive</option><option value="portrait">Portrait</option></select></label><label>Preferred package <span>*</span><select name="package" required><option value="">Select a package</option>'
booking += ''.join(f'<option value="{p["id"]}" data-type="{p["type"].lower()}">{p["type"]} — {p["level"]}</option>' for p in data['packages'])
booking += '</select></label><label>Preferred date <span>*</span><input type="date" name="date" required></label><label>Preferred location <span>*</span><input name="location" required maxlength="200" placeholder="City or location"></label><label class="full-width">Additional message<textarea name="message" rows="4" maxlength="5000" placeholder="Tell me a little about your vision…"></textarea></label></div><label class="consent"><input type="checkbox" name="consent" value="agreed" required><span>I consent to my information being used to respond to this inquiry. I have read the <a href="privacy.html">Privacy Policy</a>. <span aria-hidden="true">*</span></span></label><p class="small-label">* Required fields. An inquiry does not confirm a booking.</p><button class="button" type="submit">Send inquiry <span>↗</span></button><p id="form-status" role="status" aria-live="polite"></p></form></section>'
shell('booking.html','Booking & Pricing','Explore example automotive and portrait photography packages and prepare an inquiry for your next session.',booking)

legal = {
 'impressum.html': ('Impressum', [('Website status','This is an unfinished, editable legal placeholder. It is not a completed legal notice and has not been assessed for compliance. Complete and review it before publishing a commercial website.'),('Provider information','[Full legal name / business name]\n[Legal form, if applicable]\n[Street and house number]\n[Postal code, city, country]'),('Contact','[Working email address]\n[Further legally required contact details]'),('Business and editorial details','[Authorized representative, where applicable]\n[Register and registration number, if applicable]\n[VAT identification number, if applicable]\n[Responsible person for editorial content, if applicable]'),('Before publication','Replace every placeholder with verified information and obtain appropriate review for your business and the services used. Do not publish this draft as a completed Impressum.')]),
 'privacy.html': ('Privacy Policy', [('Draft — not ready for publication','This editable outline is not a completed privacy policy or a claim of legal compliance. Complete it based on the actual hosting, form provider, processing activities, and applicable requirements before collecting personal data.'),('Controller and contact','[Controller name, postal address, and working contact email]\n[Data protection contact, if applicable]'),('Hosting and access logs','[Identify the actual host, logged data, purposes, legal basis, retention, recipients, and any international transfers and safeguards.]'),('Booking inquiries','The form requests your name, email, photography type, preferred package, date, location, optional message, and consent. In this unconfigured version, submitting the form does not transmit these fields. Once a submission provider is connected, this section must identify that provider, the purposes and legal basis, retention, recipients, and any transfers. An inquiry is not a confirmed booking.'),('Browser storage and external resources','The supplied site code does not use analytics, advertising cookies, localStorage, or external fonts. Verify this description after configuring hosting, a form provider, or additional services.'),('Rights and complaints','[Describe applicable access, rectification, erasure, restriction, portability, objection and consent withdrawal rights, how to exercise them, and the appropriate supervisory authority.]'),('Retention and updates','[State actual retention periods or criteria, the policy date, and how changes are communicated.]')])
}
for filename,(title, sections) in legal.items():
    content = f'<section class="section page-intro"><p class="eyebrow">LEGAL / EDITABLE PLACEHOLDER</p><h1>{title}</h1><p>Draft content — complete and review before publication.</p></section><section class="section legal-copy">' + ''.join(f'<article><h2>{heading}</h2><p>{esc(copy).replace(chr(10),"<br>")}</p></article>' for heading,copy in sections) + '</section>'
    shell(filename,title,f'Editable {title.lower()} draft for Your Name Photography. Incomplete placeholder content.',content)
print('Generated 6 static HTML pages.')
